python3 $F 'https://en.wiktionary.org/wiki/քով' --note 'page 508, root Teub: Armenian kʿov side, origin unknown (Ačaṙean)' ;
python3 $F 'https://en.wiktionary.org/wiki/ته' --note 'page 508, root Teus: Persian tah bottom, possibly from *tews-' ;
python3 $F 'https://vajehyab.com/moein/سوق' --note 'page 508, root Teub: Moin sūq [ع.] bazaar, pl. aswāq' 2>&1 | tail -20

